-- Linha do tempo das cinco de demonstracao

-- -----------------------------------------------------------------------------
-- REINICIO DAS SEQUENCIAS DE IDENTITY
--
-- As linhas acima foram inseridas com id explicito, o que NAO avanca a
-- sequencia interna da coluna IDENTITY. Sem este bloco, o primeiro INSERT
-- automatico da aplicacao tentaria reutilizar um id ja ocupado e falharia
-- com violacao de chave primaria.
-- -----------------------------------------------------------------------------
ALTER TABLE CIDADAO          MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH 30));
ALTER TABLE MEMBRO_EQUIPE    MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH 4));
ALTER TABLE SERVIDOR_PUBLICO MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH 5));
ALTER TABLE DENUNCIA         MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH 126));

COMMIT;

-- -----------------------------------------------------------------------------
-- CONFERENCIA DA CARGA
-- -----------------------------------------------------------------------------
SELECT 'Denuncias'    AS entidade, COUNT(*) AS total FROM DENUNCIA
UNION ALL SELECT 'Concluidas',     COUNT(*) FROM DENUNCIA WHERE concluida_em IS NOT NULL
UNION ALL SELECT 'Em aberto',      COUNT(*) FROM DENUNCIA WHERE concluida_em IS NULL
UNION ALL SELECT 'Anonimas',       COUNT(*) FROM DENUNCIA WHERE anonimo = 1
UNION ALL SELECT 'Identificadas',  COUNT(*) FROM DENUNCIA WHERE anonimo = 0
UNION ALL SELECT 'Cidadaos',       COUNT(*) FROM CIDADAO
UNION ALL SELECT 'Historico',      COUNT(*) FROM DENUNCIA_HISTORICO
UNION ALL SELECT 'Servidores',     COUNT(*) FROM SERVIDOR_PUBLICO;
